const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $('Decode JWT + Body').first().json;
const projectRows = $('Load Project').all().map(i => i.json).filter(p => p && p.id);
const briefingRows = $('Load Briefing').all().map(i => i.json).filter(b => b && b.id);
const designRows = $input.all().map(i => i.json).filter(d => d && d.id);

if (projectRows.length === 0) {
  return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe o sin acceso por RLS', request_id: sess.request_id }}];
}
const project = projectRows[0];
const briefing = briefingRows[0] || null;
const design = designRows[0] || null;

// DB-SUA 9 aplica obligatoriamente cuando hay >12 viviendas, accesos publicos,
// o cuando el cliente declara usuario_mr (usuario con movilidad reducida).
// En reformas piso individual sin usuario MR -> aplicacion voluntaria/comercial.
const applies = !!(
  (project.num_viviendas && project.num_viviendas > 12) ||
  (project.usuario_mr && project.usuario_mr === 'true') ||
  (project.property_type === 'edificio_completo') ||
  (project.property_type === 'local_publico')
);

const systemPrompt = `Eres agent_accessibility, auditor de accesibilidad conforme DB-SUA 9 (Codigo Tecnico de la Edificacion) + Orden VIV/561/2010.

PARAMETROS CLAVE DB-SUA 9:
- Puertas paso >= 80cm (DB-SUA 9 sec 1.1)
- Pasillos >= 100cm libres (1.1)
- Bano accesible: Ø150cm libre interior; lavabo H 70-85cm; barras de apoyo
- Solado clase 2 (resistente al deslizamiento)
- Mecanismos: altura 80-120cm; vidrio templado/laminar < H 90cm
- Itinerario accesible: ancho >=120cm, pendiente <6% rampa, escalon < 5cm

REGLAS:
- applies_to_project: si false (piso individual sin usuario MR), igual da recomendaciones COMERCIALES (no obligatorias).
- overall_compliance: compliant / partial / non_compliant / not_applicable
- Cada issue con: parametro, valor_actual, valor_requerido, severidad (low/medium/high/critical), recomendacion
- commercial_argumentation: 2-3 lineas vendibles al cliente (valor anadido vivienda accesible)
- DEVUELVE SOLO JSON valido.`;

const userPrompt = `PROYECTO:
- Nombre: ${project.name}
- Tipo obra: ${project.project_type}
- Tipo inmueble: ${project.property_type}
- Superficie: ${project.property_area_m2 ?? '?'} m2
- Edad edificio: ${project.edad_edificio ?? '?'} anos
- N viviendas: ${project.num_viviendas ?? 1}
- Usuario movilidad reducida: ${project.usuario_mr ?? 'no declarado'}
- Ubicacion: ${project.location_city ?? '?'}, ${project.location_province ?? '?'}

BRIEFING:
${briefing ? '- Summary: ' + (briefing.summary?.slice(0, 500) ?? '') + '
- Rooms afectadas: ' + JSON.stringify(briefing.rooms_affected ?? []) + '
- Constraints: ' + JSON.stringify(briefing.constraints ?? []) : '(sin briefing aprobado)'}

DESIGN:
${design ? '- Titulo: ' + design.title + '
- Logica: ' + (design.intervention_logic || '').slice(0, 500) + '
- Rooms layout: ' + JSON.stringify(design.rooms_layout ?? []) : '(sin design seleccionado)'}

APLICA OBLIGATORIO: ${applies ? 'SI (DB-SUA 9 obligatorio)' : 'NO (recomendaciones comerciales)'}

TAREA:
1. Confirma applies_to_project (mi heuristica puede estar mal — ajusta segun briefing/design real).
2. Evalua overall_compliance del DESIGN actual.
3. Lista compliance_issues (cada uno con parametro DB-SUA, valor_actual segun design, valor_requerido segun norma, severidad, recomendacion concreta).
4. Lista recommendations adicionales (comercial / mejora opcional).
5. Genera commercial_argumentation para vender accesibilidad al cliente.

OUTPUT JSON:
{
  "applies_to_project": ${applies},
  "applies_reason": "...",
  "overall_compliance": "compliant|partial|non_compliant|not_applicable",
  "compliance_issues": [
    { "parametro": "...", "valor_actual": "...", "valor_requerido": "...", "severidad": "high", "recomendacion": "..." }
  ],
  "recommendations": [
    { "tipo": "comercial|obligatorio|recomendado", "texto": "..." }
  ],
  "commercial_argumentation": "..."
}`;

return [{ json: {
  user_id: sess.user_id,
  tenant_id: sess.tenant_id,
  project_id: project.id,
  request_id: sess.request_id,
  applies_heuristic: applies,
  llm_payload: {
    model: 'gpt-4o',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.2,
    max_tokens: 2000,
    response_format: { type: 'json_object' }
  }
}}];

options.queryReplacement:
={{ [
  $('Build Prompt').first().json.project_id,
  JSON.stringify({ project_id: $('Build Prompt').first().json.project_id, applies_heuristic: $('Build Prompt').first().json.applies_heuristic }),
  JSON.stringify({ request_id: $('Build Prompt').first().json.request_id, source: 'api_accessibility_audit' })
] }}

