const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0, 500), request_id: built.request_id }}];
}
const usage = llm?.usage || {};
const issues = Array.isArray(parsed.compliance_issues) ? parsed.compliance_issues : [];
const recs = Array.isArray(parsed.recommendations) ? parsed.recommendations : [];
return [{ json: {
  user_id: built.user_id,
  tenant_id: built.tenant_id,
  project_id: built.project_id,
  request_id: built.request_id,
  applies: parsed.applies_to_project ?? built.applies_heuristic,
  overall_compliance: (['compliant','partial','non_compliant','pending'].includes(parsed.overall_compliance) ? parsed.overall_compliance : 'pending'),
  issues_count: issues.length,
  output: {
    applies_to_project: parsed.applies_to_project ?? built.applies_heuristic,
    applies_reason: parsed.applies_reason || null,
    overall_compliance: (['compliant','partial','non_compliant','pending'].includes(parsed.overall_compliance) ? parsed.overall_compliance : 'pending'),
    compliance_issues: issues,
    recommendations: recs,
    commercial_argumentation: parsed.commercial_argumentation || null
  },
  model: llm?.model || 'gpt-4o',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

options.queryReplacement:
